types.c.source:
#include <stdio.h>
struct S {int x;}; struct T {int x;}; enum E {E0}; enum F {F0};
int main(void){
printf("const %d\n",__builtin_types_compatible_p(int,const int));
printf("volatile %d\n",__builtin_types_compatible_p(volatile int,int));
printf("atomic %d\n",__builtin_types_compatible_p(_Atomic(int),int));
printf("atomic_record %d\n",__builtin_types_compatible_p(_Atomic(struct S),struct S));
printf("atomic_pointer %d\n",__builtin_types_compatible_p(_Atomic(int)*,int*));
printf("pointee_const %d\n",__builtin_types_compatible_p(const int*,int*));
printf("pointer_const %d\n",__builtin_types_compatible_p(int*const,int*));
printf("unknown_array %d\n",__builtin_types_compatible_p(int[],int[5]));
printf("array_size %d\n",__builtin_types_compatible_p(int[5],int[6]));
printf("array_qualified %d\n",__builtin_types_compatible_p(const int[5],int[5]));
printf("enum_int %d\n",__builtin_types_compatible_p(enum E,int));
printf("enum_uint %d\n",__builtin_types_compatible_p(enum E,unsigned int));
printf("distinct_enums %d\n",__builtin_types_compatible_p(enum E,enum F));
printf("distinct_structs %d\n",__builtin_types_compatible_p(struct S,struct T));
printf("incomplete %d\n",__builtin_types_compatible_p(struct U,struct U));
printf("function_old %d\n",__builtin_types_compatible_p(int(int),int()));
printf("function_float_old %d\n",__builtin_types_compatible_p(int(float),int()));
printf("function_variadic %d\n",__builtin_types_compatible_p(int(int,...),int(int)));
printf("function_atomic %d\n",__builtin_types_compatible_p(int(_Atomic(int)),int(int)));
printf("function_return_qual %d\n",__builtin_types_compatible_p(const int(void),int(void)));
}

